const nodes=[[0,-24],[0,-14],[0,5],[11,5],[0,53],[0,88],[25,96],[-24,98],[0,-48],[-49,-48],[-104,-48],[-124,-48],[-124,-78],[-124,-95],[15,87],[32,90],[27,79],[-8,-7]];
const edges=[[0,1],[1,2],[2,3],[2,4],[4,5],[5,6],[5,7],[0,8],[8,9],[9,10],[10,11],[11,12],[12,13],[5,14],[14,6],[6,15],[15,16],[14,16],[2,17]];
const audio=new KarlstadAudio(), canvas=$('renderCanvas'), ui=$('ui');
let world,engine,softwareRenderer=null,mode='loading',time=0,introTime=0,last=0,yaw=0,pitch=0,bob=0,scanRecoil=0,toastUntil=0,guide=[],guideIndex=0,lookTime=-10,quality=matchMedia('(pointer:coarse), (max-width:700px)').matches?'balanced':'high',qualityAuto=false,frameSamples=0,slowTime=0,rideTime=0,rideStart=0,modalType='',lastFocus=null,sceneMap=null,mapMarkers=[],mapLoading=false,jumping=0,jumpVelocity=0;
let playStyle='city',thirdPerson=true,actionGame,zombieGame,controls,cityData,liveWeather=true,crouching=false,velocityX=0,velocityZ=0,cameraSnap=true,lookSensitivity=1,cityReturn=null,profileNear=null;
const keys=new Set(),input={x:0,y:0,sprint:false,autoSprint:false,crouch:false},player={x:0,z:-24};let save=readSave();let scanning=false,seen=new Set(),hudClock=0,screenClock=0;
function readSave(){try{const v=JSON.parse(localStorage.getItem(STORAGE));if(!v||!Number.isInteger(v.done)||v.done<0||v.done>5)throw 0;return {done:v.done,fragments:Array.isArray(v.fragments)?[...new Set(v.fragments.filter(i=>Number.isInteger(i)&&i>=0&&i<3))]:[]}}catch{return {done:0,fragments:[]}}}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(save))}catch{}}
const active=()=>Math.min(save.done,4),current=()=>MISSIONS[active()],score=()=>MISSIONS.slice(0,save.done).reduce((a,m)=>a+m.xp,0),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),mix=(a,b,t)=>a+(b-a)*t;
function deltaAngle(a,b){return Math.atan2(Math.sin(b-a),Math.cos(b-a))}
function setMode(m){mode=m;ui.dataset.mode=m;ui.dataset.style=playStyle;keys.clear();input.x=input.y=0;input.sprint=false;velocityX=velocityZ=0;controls?.reset();if(world){world.scanner.setEnabled(m==='play'&&!thirdPerson&&playStyle==='city');world.hero.root.setEnabled(m==='intro'||m==='play'&&thirdPerson||m==='paused'&&thirdPerson)}if(m!=='play'&&document.pointerLockElement)document.exitPointerLock?.()}
function toast(title,text,seconds=4){$('toastTitle').textContent=title;$('toastText').textContent=text;$('toast').classList.add('visible');toastUntil=time+seconds}
function target(){if(playStyle==='zombie'&&zombieGame)return zombieGame.current(player);if(playStyle==='action'&&actionGame){const p=actionGame.current();return {...p,node:5,name:p.label}}if(scanning){const i=[0,1,2].find(n=>!save.fragments.includes(n));if(i!==undefined){const pos=world.fragments[i].root.position;return {x:pos.x,z:pos.z,node:14+i,name:'LJUSFRAGMENT '+(i+1)}}}return {...current(),name:current().short}}
function stopGuide(){guide=[];guideIndex=0;$('guideButton').classList.remove('active');$('guideButton').textContent='↗ FÖLJ SPÅRET'}
function route(start,end){let dist=nodes.map(()=>Infinity),prev=nodes.map(()=>-1),q=new Set(nodes.map((_,i)=>i));dist[start]=0;while(q.size){let u=[...q].reduce((a,b)=>dist[a]<dist[b]?a:b);q.delete(u);if(u===end||!isFinite(dist[u]))break;for(const edge of edges){let v=edge[0]===u?edge[1]:edge[1]===u?edge[0]:-1;if(v<0||!q.has(v))continue;let d=dist[u]+Math.hypot(nodes[u][0]-nodes[v][0],nodes[u][1]-nodes[v][1]);if(d<dist[v]){dist[v]=d;prev[v]=u}}}let path=[],u=end;while(u!==-1){path.unshift(nodes[u]);u=prev[u]}return path}
function startGuide(){if(mode!=='play')return;if(playStyle==='action'){toast('Följ solens markör','Styr med vänster spak. Ytterkanten ger sprint. Hoppa och ducka med högerknapparna.',4);return}if(guide.length){stopGuide();return}const t=target();let nearest=0;for(let i=1;i<nodes.length;i++)if(Math.hypot(player.x-nodes[i][0],player.z-nodes[i][1])<Math.hypot(player.x-nodes[nearest][0],player.z-nodes[nearest][1]))nearest=i;guide=route(nearest,t.node).map(p=>({x:p[0],z:p[1]}));guide.push({x:t.x,z:t.z});guideIndex=0;$('guideButton').textContent='Ⅱ PAUSA GUIDNING';$('guideButton').classList.add('active');toast('Följ stadens spår','Du går automatiskt. Dra för att se dig omkring. Styr själv för att avbryta.',4)}
function refresh(){if(playStyle==='zombie'){refreshZombie();return}if(playStyle==='action'){refreshAction();return}const m=current(),done=save.done===5;$('missionNumber').textContent=done?'05 / 05':String(active()+1).padStart(2,'0')+' / 05';$('missionKind').textContent=done?'STADENS SOLSIGILL':m.kind;$('missionTitle').textContent=done?'Karlstad är bara början.':m.title;$('missionHint').textContent=done?'Alla fem uppdrag klara. Fortsätt utforska eller se stadens aktuella tips.':scanning?`Scanna tre ljusfragment i trädgården. ${save.fragments.length} / 3 funna.`:m.hint;$('score').textContent=score()+' XP';$('progressDots').innerHTML=MISSIONS.map((_,i)=>`<i class="${i<save.done?'done':i===save.done?'current':''}"></i>`).join('');world.beacons.slice(0,5).forEach((b,i)=>b.root.setEnabled(!done&&i===active()&&!scanning));world.fragments.forEach((b,i)=>b.root.setEnabled(scanning&&!save.fragments.includes(i)));$('guideButton').hidden=done}
function startPlay(){if(playStyle==='zombie')zombieGame.stop();audio.setTheme('city');playStyle='city';actionGame?.root.setEnabled(false);introTime=24;$('fade').style.opacity=0;$('introTitles').style.opacity=0;thirdPerson=true;cameraSnap=true;world.hero.root.setEnabled(true);setMode('play');if(save.done>0){const p=nodes[current().node];player.x=p[0];player.z=p[1]+(current().id==='park'?7:-7)}yaw=0;pitch=.16;world.camera.fov=.98;refresh();toast('Välkommen till Karlstad','Följ spåret, möt Sola och Fröding eller välj Soljakten i pausmenyn.',7);if(save.done===5)finalPanel()}
function animateHero(t){const hero=world.hero;hero.root.position.set(0,0,-27+Math.max(0,t-11)*.68);hero.root.rotation.y=0;hero.animate(1/60,1.6,false,0,t)}
const introKeys=[{t:0,p:[-67,35,60],look:[-18,7,116]},{t:6,p:[-6,18,85],look:[25,6,111]},{t:12,p:[9,13,43],look:[31,7,62]},{t:17,p:[-3,3.7,-29],look:[0,1.4,-20]},{t:23,p:[0,2.8,-30],look:[0,1.6,-19]}];
function cinematicCamera(keys,t){let i=0;while(i<keys.length-2&&t>keys[i+1].t)i++;let a=keys[i],b=keys[i+1],f=clamp((t-a.t)/(b.t-a.t),0,1),s=f*f*(3-2*f);const B=BABYLON;world.camera.position.set(...a.p.map((v,n)=>mix(v,b.p[n],s)));world.camera.setTarget(new B.Vector3(...a.look.map((v,n)=>mix(v,b.look[n],s))))}
function intro(dt){introTime+=dt;cinematicCamera(introKeys,introTime);animateHero(introTime);world.scanner.setEnabled(false);$('introTitles').style.opacity=introTime>16?'0':introTime<1?'0':'1';$('introTitles').style.transform=introTime>16?'translateY(12px)':'none';$('introCaption').textContent=introTime<7?'VÄRMLANDS MUSEUM · SANDGRUNDSUDDEN':introTime<14?'SANDGRUND · STORA TORGET':'DITT ÄVENTYR BÖRJAR HÄR';if(introTime>=23)startPlay()}
function startAction(){
 if(!world)return;if(playStyle==='zombie'){zombieGame.stop();$('zombieButton').innerHTML='☣ <span>ZOMBIE</span>';}audio.setTheme('city');if(playStyle==='city')cityReturn={x:player.x,z:player.z,yaw,pitch};playStyle='action';thirdPerson=true;stopGuide();$('modal').hidden=true;$('mapOverlay').hidden=true;$('fade').style.opacity=0;$('introTitles').style.opacity=0;introTime=24;player.x=0;player.z=52;yaw=0;pitch=.20;world.hero.root.rotation.y=0;jumping=jumpVelocity=0;cameraSnap=true;actionGame.reset();world.beacons.forEach(b=>b.root.setEnabled(false));setMode('play');refreshAction();toast('Soljakten · 120 sekunder','Samla 14 solar. Spring, hoppa och ducka. Ingen trafik, inga vapen – bara stadens ljus.',6);
}
