function refreshZombie(){if(!zombieGame)return;const a=zombieGame.state,t=zombieGame.current(player),near=Math.hypot(player.x-t.x,player.z-t.z)<2.9;
 $('missionNumber').textContent=a.powered+' / 3 SOLFYRAR';$('missionKind').textContent='ÖVERLEVNAD';$('score').textContent=a.points+' P';$('guideButton').hidden=true;$('progressDots').innerHTML='';
 $('missionTitle').textContent=a.powered<3?(near?'HÅLL ZONEN · '+Math.round(t.charge/3*100)+'%':t.name):a.remaining>0?'ÖVERLEV TILL GRYNING':'EVAKUERA VID MUSEET';
 $('missionHint').textContent=a.powered<3?'Stanna i ljusringen i 3 sekunder. Solfyren ger sköld och energi.':a.remaining>0?'Håll zombierna borta. Evakueringen öppnas vid gryningen.':a.extract>0?'Håll evakueringszonen · '+Math.round(a.extract/3*100)+'%':'Nå den gröna ringen vid museet. Håll zonen i 3 sekunder.';
 $('zombieHealth').textContent=Math.ceil(a.health);$('zombieEnergy').textContent=Math.floor(a.energy)+'%';$('healthFill').style.width=a.health+'%';$('energyFill').style.width=a.energy+'%';$('healthMeter').setAttribute('aria-valuenow',Math.ceil(a.health));$('energyMeter').setAttribute('aria-valuenow',Math.floor(a.energy));
 $('zombieTime').textContent=a.remaining>0?String(Math.floor(Math.ceil(a.remaining)/60)).padStart(2,'0')+':'+String(Math.ceil(a.remaining)%60).padStart(2,'0'):'GRYNING';$('zombieWave').textContent=String(a.wave).padStart(2,'0');$('zombieDamage').style.opacity=a.damage>0?'.8':a.health<30?'.22':'0';$('zombieHit').style.opacity=a.hitMarker>0?'1':'0';
 $('novaLabel').textContent=a.novaCooldown>0?Math.ceil(a.novaCooldown)+' SEK':'SOLNOVA · Q';$('novaButton').disabled=a.novaCooldown>0||a.energy<25;
 $('zombieNotice').textContent=a.energy<8?'SOLENERGIN LADDAS · SLÄPP AVTRYCKAREN':a.combo>1&&a.hitMarker>0?'NEUTRALISERAD · KOMBO ×'+a.combo:a.powered===3&&a.remaining<=0?'EVAKUERING ÖPPEN · MUSEET':'';
}
function zombieResult(won){const a=zombieGame.state;let best=a.points;try{best=Math.max(+localStorage.getItem('karlstad-zombie-best')||0,a.points);localStorage.setItem('karlstad-zombie-best',String(best))}catch{}audio.fx(won?'win':'hurt');panel(`<span class="eyebrow">ZOMBIE APOCALYPSE KARLSTAD</span><div class="dialog-icon">${won?'☀':'☣'}</div><h2 id="dialogTitle">${won?'Du tog staden tillbaka.':'Mörkret hann ikapp.'}</h2><p>${won?'Solfyrarna lyser igen. Du överlevde och nådde evakueringen.':'Håll dig i rörelse, använd solnovan när zombierna kommer nära och ladda skölden vid solfyrarna.'}</p><div class="fact">${a.points} POÄNG · REKORD ${best}<br>${a.neutralized} neutraliseringar · ${a.powered} / 3 solfyrar<br>${Math.floor(a.elapsed)} sekunder överlevda</div><button class="primary" data-action="zombie">SPELA IGEN →</button><button class="secondary" data-action="city">TILL STADSÄVENTYRET</button>`,'zombieResult');}
function zombiePause(){panel(`<span class="eyebrow">ZOMBIE APOCALYPSE · PAUSAD</span><h2 id="dialogTitle">Håll ljuset levande.</h2><p>Solstrålar neutraliserar zombier i 7 sekunder. Solenergin laddas när du släpper avtryckaren.<br>WASD: rör dig · mus / F: skjut · Q: solnova.<br>Shift: sprint · mellanslag: hopp · C: ducka.<br>Mobil: vänster spak för rörelse. Håll och dra på solknappen för att skjuta och sikta.</p><div class="fact">Ladda tre solfyrar. Överlev till gryningen och håll evakueringszonen vid museet i 3 sekunder.</div><p>KAMERAKÄNSLIGHET</p><label class="sensitivity-label">Lugnare <input id="lookSensitivity" aria-label="Kamerakänslighet" type="range" min="0.5" max="1.7" step="0.1" value="${lookSensitivity}"> Snabbare</label><p>GRAFIK</p><div class="settings-row">${[['mobile','MOBIL'],['balanced','BALANSERAD'],['high','FILMISK']].map(([id,s])=>`<button data-quality="${id}" class="${quality===id?'selected':''}">${s}</button>`).join('')}</div><button class="primary" data-action="resume">FORTSÄTT →</button><button class="secondary" data-action="zombie">NY ÖVERLEVNADSRUNDA</button><button class="secondary" data-action="city">TILL STADSÄVENTYRET</button><div class="source">Dina stadsuppdrag är sparade. Överlevnadsrekordet sparas separat på den här enheten.</div>`,'zombiePause');}
function refreshAction(){if(!actionGame)return;const a=actionGame.state,p=actionGame.current();$('missionNumber').textContent=`${a.index} / ${a.total}`;$('missionKind').textContent='SOLJAKTEN · ACTION';$('missionTitle').textContent=p.label;$('missionHint').textContent=p.type==='duck'?'Tryck DUCKA. Hämta solen under den turkosa porten.':p.type==='jump'?'Tryck HOPPA strax före det lila hindret.':'Följ den stora solens markör. Hitta nästa gömma.';$('score').textContent=a.points+' P';$('guideButton').hidden=true;$('progressDots').innerHTML=Array.from({length:a.total},(_,i)=>`<i class="${i<a.index?'done':i===a.index?'current':''}"></i>`).join('');$('actionSeconds').textContent=Math.ceil(a.seconds);$('actionCombo').textContent=a.combo>1?'KOMBO ×'+a.combo:'SAMLA SOLAR';$('actionCount').textContent=`${a.index} / ${a.total}`;}
function actionResult(won){const a=actionGame.state;let best=0;try{best=Math.max(+localStorage.getItem('karlstad-action-best')||0,a.points);localStorage.setItem('karlstad-action-best',String(best))}catch{}audio.fx(won?'win':'click');panel(`<span class="eyebrow">SOLJAKTEN · ${won?'ALLA SOLAR HITTADE':'TIDEN ÄR UTE'}</span><div class="dialog-icon">✳</div><h2 id="dialogTitle">${won?'Du fick Karlstad att lysa.':'En runda till?'}</h2><p>${a.index} av ${a.total} solar hittade. ${won?'Stadens solsigill är ditt.':'Lär känna genvägarna och försök slå ditt rekord.'}</p><div class="fact">${a.points} POÄNG · REKORD ${best}<br>${won?Math.ceil(a.seconds)+' sekunder kvar':'Spring · ducka · hoppa · hitta'}</div><button class="primary" data-action="action">SPELA SOLJAKTEN IGEN →</button><button class="secondary" data-action="city">TILL STADSÄVENTYRET</button>`,'actionResult');}
function profilePanel(id){const sola=id==='sola';panel(`<span class="eyebrow">MÖT KARLSTADS BERÄTTELSER</span><div class="dialog-icon">${sola?'☀':'✒'}</div><h2 id="dialogTitle">${sola?'Sola i Karlstad':'Gustaf Fröding'}</h2><p>${sola?'Eva Lisa Holtz levde 1739–1818. Hon arbetade som servitris och drev ett eget värdshus. Hennes glada sätt gav henne namnet Sola.':'Gustaf Fröding föddes på Alsters herrgård 1860. Han blev poet och journalist och arbetade på Karlstads-Tidningen.'}</p><div class="fact">${sola?'SOLAS UPPTÄCKARTIPS<br>Hjälp någon hitta i staden. Bibliotekets tillfälliga hem är Arkaden. Följ det första uppdraget dit.':'FRÖDINGS UPPTÄCKARTIPS<br>Stanna vid älven och lägg märke till ett ljud, en färg och ett ord. Vad skulle din egen rad om Karlstad vara?'}</div><button class="primary" data-action="resume">UTFORSKA VIDARE →</button><button class="secondary" data-action="cityInfo">STADEN I SIFFROR</button><div class="source">Historiskt inspirerad originalfigur. Speltipsen är nyskrivna och är inte citat.<br><a href="${sola?'https://sv.wikipedia.org/wiki/Sola_i_Karlstad':'https://frodingsallskapet.se/om-froding/biografi/'}" target="_blank" rel="noopener noreferrer">Läs om ${sola?'Eva Lisa Holtz':'Gustaf Fröding'} ↗</a></div>`,'profile')}
function cityInfoPanel(){const w=cityData.weather,p=cityData.population,stamp=w?new Date(w.time).toLocaleString('sv-SE',{timeZone:'Europe/Stockholm',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'';panel(`<span class="eyebrow">KARLSTAD · EN LEVANDE STAD</span><h2 id="dialogTitle">Staden utanför spelet.</h2><div class="fact"><strong>${w?Math.round(w.temperature)+'° · '+w.wind.toFixed(1)+' m/s':'Väderprognosen är inte tillgänglig'}</strong><br>${w?'SMHI-prognos för '+stamp+'.':'Spelet använder sitt soliga grundljus.'}<br>${w?'Molnighet '+w.cloud+'/8 · nederbörd '+w.rain+' mm':''}</div><p>SMHI:s prognos kan styra solljus och molntäcke i spelvärlden. Du kan också välja det soliga grundljuset.</p><div class="settings-row"><button data-weather="live" class="${liveWeather?'selected':''}">PROGNOSLJUS</button><button data-weather="sunny" class="${!liveWeather?'selected':''}">SOLIGT LJUS</button></div><div class="fact population-card"><strong>${p.value.toLocaleString('sv-SE')} invånare</strong><br>Karlstads kommun · 31 december ${p.year}<br>${p.status==='api'?'Hämtat från SCB:s API':'Daterad referens från Karlstads kommun / SCB'}</div><p>Folkmängden gäller hela kommunen. Den används som stadsfakta och ändrar inte antalet figurer på gatan.</p><button class="primary" data-action="resume">TILLBAKA TILL SPELET</button><div class="source">Väder: <a href="https://www.smhi.se/data/om-smhis-data/villkor-for-anvandning" target="_blank" rel="noopener noreferrer">SMHI · CC BY 4.0 ↗</a>. Prognosvärden omvandlas till stiliserat ljus och moln.<br>Befolkning: <a href="https://www.scb.se/vara-tjanster/oppna-data/pxwebapi/pxwebapi-v2/" target="_blank" rel="noopener noreferrer">SCB PxWeb v2 ↗</a> · tabell TAB5557, region 1780.<br><a href="https://karlstad.se/kommun-och-politik/kommunfakta/statistik" target="_blank" rel="noopener noreferrer">Kommunens befolkningsstatistik ↗</a></div>`,'cityInfo');}
function toggleCamera(){if(playStyle!=='city')return;thirdPerson=!thirdPerson;cameraSnap=true;world.hero.root.setEnabled(thirdPerson);world.scanner.setEnabled(!thirdPerson);$('cameraButton').textContent=thirdPerson?'3P':'1P';$('cameraButton').setAttribute('aria-label',thirdPerson?'Byt till förstaperson':'Byt till tredjeperson');toast(thirdPerson?'Kamera bakom figuren':'Förstaperson','Tryck V eller kameraknappen för att byta.',2)}
