function eventsPanel(){let now=new Date(),currentEvent=now>=new Date(2026,4,30)&&now<new Date(2026,10,9);panel(`<span class="eyebrow">LEVANDE STAD · HIDDEN GEMS</span><div class="dialog-icon">✦</div><h2 id="dialogTitle">Nästa upptäckt är verklig.</h2><p>Utställningar, föreställningar och nya mötesplatser kan bli tidsbegränsade uppdrag i nästa version.</p>${currentEvent?'<div class="fact"><strong>SANDGRUND LARS LERIN</strong><br>Gästutställning med Sven X:et Erixson, 30 maj–8 november 2026.<br><a href="https://sandgrund.org/sandgrund/" target="_blank" rel="noopener noreferrer">Se aktuell information hos Sandgrund ↗</a></div>':''}<a class="primary" href="https://visitkarlstad.se/visit-karlstad/evenemang" target="_blank" rel="noopener noreferrer">STADENS EVENEMANG ↗</a><button class="secondary" data-action="resume">FORTSÄTT UTFORSKA</button><div class="source">Kontrollera datum, entré och öppettider hos arrangören. Inga sponsoravtal eller verkliga erbjudanden är kopplade till piloten.</div>`,'events')}
