function scan(){if(mode!=='play'||playStyle!=='city')return;if(profileNear){profilePanel(profileNear.id);return}scanRecoil=.12;$('scanFlash').style.opacity='.55';setTimeout(()=>$('scanFlash').style.opacity=0,240);audio.fx('scan');const t=target(),dist=Math.hypot(player.x-t.x,player.z-t.z);if(save.done===5){finalPanel();return}if(dist>7){toast('Signalen finns längre bort',`${Math.round(dist)} meter i spelvärlden. Följ markören eller välj Följ spåret.`,3);return}stopGuide();if(scanning){let index=[0,1,2].find(i=>!save.fragments.includes(i));save.fragments.push(index);persist();refresh();audio.fx('win');if(save.fragments.length===3){completeMission()}else{toast('Ljusfragment hittat',`${save.fragments.length} / 3 · Scanna nästa signal i trädgården.`,4)}}else missionPanel()}
