 if(Math.abs(fw)+Math.abs(side)>.01){manual=true;if(guide.length)stopGuide();const len=Math.max(1,Math.hypot(fw,side));dx=(Math.sin(yaw)*fw+Math.cos(yaw)*side)/len;dz=(Math.cos(yaw)*fw-Math.sin(yaw)*side)/len;}
