 const speed=crouching?(playStyle==='zombie'?3.7:2.8):sprint?(playStyle==='zombie'?11.8:playStyle==='action'?10:8.2):(playStyle==='zombie'?7.6:playStyle==='action'?6.3:4.8),response=1-Math.exp(-dt*(dx||dz?25:42));velocityX=mix(velocityX,dx*speed,response);velocityZ=mix(velocityZ,dz*speed,response);
