 if(moving)bob+=dt*(sprint?11:7.5);world.hero.root.position.set(player.x,jumping,player.z);if(moving)world.hero.root.rotation.y+=deltaAngle(world.hero.root.rotation.y,Math.atan2(velocityX,velocityZ))*(1-Math.exp(-dt*18));world.hero.animate(dt,actualSpeed,crouching,jumping,time);
