 if(playStyle==='action'){$('interactButton').hidden=true;$('talkButton').hidden=true;const event=actionGame.update(dt,player,crouching,jumping);if(event?.pickup){audio.fx('win');refreshAction();$('scanFlash').style.opacity='.25';setTimeout(()=>$('scanFlash').style.opacity=0,140)}if(event?.done){refreshAction();actionResult(event.won)}return;}
 const near=distance<=7;$('interactButton').hidden=!near;$('interactText').textContent=save.done===5?'SE SOLSIGILLET':scanning?'SCANNA FRAGMENT':'UNDERSÖK PLATSEN';$('reticle').classList.toggle('ready',near);if(near&&!seen.has(t.name)){seen.add(t.name);audio.fx('click')}
